-- 商品规格参数与属性填充（自动生成；改 backend/script/gen/ 后重跑）
-- 权威来源：亚德客官方样本 PDF（cdn.snway.cn 镜像）+ MOB 厂商公开资料
--   气缸类 SC/SDA/MA/MAL/TN 共 24 页 —— 无一页含重量
--   气源处理 AR-BR / AFR-BFR / AFC-BFC 共 6 页 —— 含「重量」行，已录入
--   气动接头 APC 2 页 —— 仅型号对照表，无规格无重量
-- ⚠️ 样本重量是产品净重，不是含包装的毛重。运费按毛重与体积重计，仍须实测。
CREATE TABLE IF NOT EXISTS `ec_sku_spec` (
  `sku_id` bigint NOT NULL, `spec` json NULL, `confidence` varchar(8) NULL,
  `spec_source` varchar(64) NULL, `create_time` datetime(3) NULL, `update_time` datetime(3) NULL,
  PRIMARY KEY (`sku_id`), KEY `idx_conf` (`confidence`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='SKU规格参数（型号解析+官方样本，非实测）';







