SELECT '有规格的SKU' c, COUNT(*) n FROM ec_sku_spec;
SELECT '含官方样本参数' c, COUNT(*) n FROM ec_sku_spec
 WHERE JSON_EXTRACT(spec,'$."保证耐压力"') IS NOT NULL OR JSON_EXTRACT(spec,'$."试验压力"') IS NOT NULL;
SELECT '有样本重量' c, COUNT(*) n FROM ec_sku_spec WHERE JSON_EXTRACT(spec,'$."样本重量"') IS NOT NULL;
SELECT '有接管口径' c, COUNT(*) n FROM ec_sku_spec WHERE JSON_EXTRACT(spec,'$."接管口径"') IS NOT NULL;
